- `pub fn new(n: i32, m: i32) -> Result<ChTrie, ChTrieError>` mirroring chtrie_alloc: regulate n,m to >=1; if n>INT_MAX||m>INT_MAX -> Err(ERANGE) (with i32 params this is automatic, but keep the overflow check `MIN(INT_MAX, usize::MAX) - (n-1) < (n-1)/3` -> Err(ERANGE)); ecap = (n-1)+(n-1)/3; etab = vec![empty; ecap]; idxpool = vec![0; n]; idxmax=1; idxptr=0.
- `pub fn walk(&mut self, from: i32, sym: i32, creat: bool) -> i32` mirroring chtrie_walk: h = (from as usize * alphsz as usize + sym as usize) % ecap; search etab[h] for edge with matching from,sym -> return its to; if creat: if idxptr==idxpool.len() && idxmax>=maxn -> return -1 (ENOMEM); push Edge{from,sym,to} at front of etab[h] (C prepends); to = if idxptr < idxpool.len() { let v = idxpool[idxptr]; idxptr-=1; v } else { let v = idxmax; idxmax+=1; v }; return to. Otherwise return -1.
- `pub fn del(&mut self, from: i32, sym: i32)` mirroring chtrie_del: find edge in etab[h], remove it, push its `to` onto idxpool (idxpool.push(to)), if not found do nothing.
- `impl Drop for ChTrie` (no-op needed with Vecs, but include for API parity).
- `pub enum ChTrieError { Erange, Enomem }` with Display.
- Keep the same hash formula and semantics exactly. No unsafe.

C SOURCE (src/chtrie.c):
```c
#include <stddef.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>
#include "chtrie.h"
#define SZ_MAX ((size_t)-1)
#define MIN(x, y) ((x)<(y)?(x):(y))

chtrie *chtrie_alloc(size_t n, size_t m)
{
	chtrie *tr;

	if (n < 1) n = 1;
	if (m < 1) m = 1;
	if (n > INT_MAX || m > INT_MAX) {
		errno = ERANGE;
		goto err;
	}
	if (MIN(INT_MAX, SZ_MAX) - (n-1) < (n-1) / 3) {
		errno = ERANGE;
		goto err;
	}
	if (!(tr = calloc(1, sizeof *tr)))
		goto err;
	tr->maxn = n;
	tr->alphsz = m;
	tr->ecap = (n-1) + (n-1)/3;
	if (!(tr->etab = calloc(tr->ecap, sizeof tr->etab[0])))
		goto free_tr;
	if (!(tr->idxpool = calloc(n, sizeof tr->idxpool[0])))
		goto free_ecap;
	tr->idxmax = 1;
	tr->idxptr = tr->idxpool;
	return tr;
free_ecap:
	free(tr->etab);
free_tr:
	free(tr);
err:
	return NULL;
}

int chtrie_walk(chtrie *tr, int from, int sym, int creat)
{
	struct chtrie_edge *p;
	unsigned long h;

	h = (unsigned long)from*tr->alphsz + sym;
	h %= tr->ecap;
	for (p = tr->etab[h]; p; p = p->next)
		if (p->from == from && p->sym == sym)
			return p->to;
	if (creat) {
		if (tr->idxptr == tr->idxpool && tr->idxmax >= tr->maxn) {
			errno = ENOMEM;
			return -1;
		}
		if (!(p = malloc(sizeof *p)))
			return -1;
		p->next = tr->etab[h];
		tr->etab[h] = p;
		p->from = from;
		p->sym = sym;
		if (tr->idxptr != tr->idxpool)
			p->to = *--tr->idxptr;
		else
			p->to = tr->idxmax++;
		return p->to;
	}
	return -1;
}

void chtrie_del(chtrie *tr, int from, int sym)
{
	struct chtrie_edge *p, *q;
	unsigned long h;

	h = (unsigned long)from*tr->alphsz + sym;
	h %= tr->ecap;
	for (p = tr->etab[h], q = NULL; p; q = p, p = p->next)
		if (p->from == from && p->sym == sym)
			break;
	if (!p)
		return;
	if (q)
		q->next = p->next;
	else
		tr->etab[h] = NULL;
	*tr->idxptr++ = p->to;
	free(p);
}

void chtrie_free(chtrie *tr)
{
	struct chtrie_edge *p, *q;
	int i;

	for (i = 0; i < tr->ecap; i++) {
		p = tr->etab[i];
		while (p) {
			q = p->next;
			free(p);
			p = q;
		}
	}
	free(tr->etab);
	free(tr->idxpool);
	free(tr);
}
```

STEP 4 — Run `cargo build` and fix any errors until it compiles cleanly. Report: files created, the exact public API, and the cargo build output (success/failure)."}

